utter.onerror=function(e){if(token!==tlSpeechToken)return;if(e.error==='canceled'||e.error==='interrupted'){tlReading=false;return}speakNext()};
window.speechSynthesis.speak(utter);
}
window.speechSynthesis.getVoices();
speakNext();
}
